        [choice("model", "Welche Rechnung ergibt den Rest in Zentimetern?", "Which calculation gives the remainder in centimetres?", [("a", "500 − 3 · 125", "500 − 3 × 125"), ("b", "5 − 3 · 125", "5 − 3 × 125"), ("c", "500 − 125", "500 − 125")], "a", s), number("left", "Wie viele Zentimeter Seil bleiben übrig?", "How many centimetres of rope remain?", 125, s, unit="cm")],
