        [number("missing", "Wie lang ist das dritte Teilstück in Metern?", "How long is the third section in metres?", 1150, s, unit="m"), choice("mixed", "Welche gemischte Schreibweise passt zu dieser Länge?", "Which mixed-unit notation matches that length?", [("a", "1 km 150 m", "1 km 150 m"), ("b", "1 km 15 m", "1 km 15 m"), ("c", "11 km 50 m", "11 km 50 m")], "a", s)],
